import {registerCatalog,t,localizedText,localizeMarkedNodes,onLocaleChange} from './i18n.js';
import appEnglish from './locales/historical-app.en.js';
import appChinese from './locales/historical-app.zh-Hant.js';
registerCatalog('historical-app',{en:appEnglish,'zh-Hant':appChinese});
const appCopyKeys=new Map(Object.entries(appEnglish).map(([key,value])=>[value,`historical-app.${key}`]));
const appCopy=(source,params={})=>appCopyKeys.has(source)?t(appCopyKeys.get(source),params):source;
// Engine errors use a known semicolon-delimited list; preserve unknown messages verbatim.
const appError=message=>String(message).split('; ').map(source=>appCopy(source)).join('; ');
const appMark=(source,params={})=>appCopyKeys.has(source)?localizedText(appCopyKeys.get(source),params):esc(source);
const appTextBindings=new Map();
const appAttrs=(source,params={})=>`data-i18n="${esc(appCopyKeys.get(source))}" data-i18n-params="${esc(JSON.stringify(params))}"`;
const appLeaf=(tag,source,params={},attributes='')=>`<${tag} ${attributes} ${appAttrs(source,params)}>${esc(appCopy(source,params))}</${tag}>`;
function appText(node,source,params={}){if(!node)return;const shown=appCopyKeys.has(source)?appCopy(source,params):appError(source);appTextBindings.set(node,{source,params,shown});node.textContent=shown;}
onLocaleChange(()=>{for(const [node,entry] of appTextBindings){if(node.isConnected===false||node.children.length||node.textContent!==entry.shown){appTextBindings.delete(node);continue;}entry.shown=appCopyKeys.has(entry.source)?appCopy(entry.source,entry.params):appError(entry.source);node.textContent=entry.shown;}localizeMarkedNodes(document);
 for(const option of document.querySelectorAll('#company option')){const company=companies.find(c=>c.ticker===option.value);const fallback=popular.find(([ticker])=>ticker===option.value);if(company||fallback){const name=company?.name||fallback[1];option.setAttribute('data-i18n-params',JSON.stringify({ticker:option.value,name:appCopy(name),needed:company?.snapshots.length?'':appCopy(' · import needed')}));}}
 localizeMarkedNodes(document);
 for(const node of document.querySelectorAll('[data-app-error]'))node.textContent=appError(node.dataset.appError);
});
